const { deliver } = require('/workspace/src/dispatcher.js');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function expectCall(label, fn, match) {
  try { const v = await fn(); console.log('PASS', label, match(v)); }
  catch (e) { console.log('PASS', label, 'threw:', e.message); }
}

(async () => {
  // 1: retries a thrown network error then succeeds; sends X-Event-Id each time
  {
    const io = { post: jestLike([
      { err: new Error('ECONNRESET') },
      { res: { status: 200, body: 'ok' } },
    ]) };
    const res = await deliver(io, { id: 'evt-1', type: 'ping' });
    console.log('retry-after-error count=', io.post.mock.calls.length, 'res=', res.body);
    console.log('header=', io.post.mock.calls[0][2].headers);
  }
  // 2: retries a 502 response then succeeds
  {
    const io = { post: jestLike([
      { res: { status: 502 } },
      { res: { status: 200 } },
    ]) };
    const res = await deliver(io, { id: 'evt-2' });
    console.log('retry-after-502 count=', io.post.mock.calls.length, 'status=', res.status);
  }
  // 3: gives up after MAX_ATTEMPTS (3) and rethrows last error
  {
    const io = { post: jestLike([{ err: new Error('boom') }, { err: new Error('boom') }, { err: new Error('boom') }]) };
    try { await deliver(io, { id: 'evt-3' }); console.log('FAIL no-throw'); }
    catch (e) { console.log('give-up count=', io.post.mock.calls.length, 'err=', e.message); }
  }
  // 4: no retry for 4xx; X-Event-Id uses eventId fallback
  {
    const io = { post: jestLike([{ res: { status: 400 } }]) };
    const res = await deliver(io, { eventId: 'evt-4' });
    console.log('no-retry-4xx count=', io.post.mock.calls.length, 'status=', res.status,
      'header=', io.post.mock.calls[0][2].headers['X-Event-Id']);
  }
  // 5: response without status is treated as delivered
  {
    const io = { post: jestLike([{ res: { ok: true } }]) };
    const res = await deliver(io, { id: 'evt-5' });
    console.log('no-status count=', io.post.mock.calls.length, 'ok=', res.ok);
  }
  // 6: no id on event -> no header, no retry
  {
    const io = { post: jestLike([{ res: { status: 200 } }]) };
    const res = await deliver(io, { type: 'x' });
    console.log('no-id count=', io.post.mock.calls.length, 'headers=', io.post.mock.calls[0][2].headers);
  }
})();

// tiny jest.fn-like mock
function jestLike(sequence) {
  const fn = async () => {
    const step = sequence[fn.mock.calls.length] || sequence[sequence.length - 1];
    fn.mock.calls.push(Array.from(arguments));
    if (step.err) throw step.err;
    return step.res;
  };
  fn.mock = { calls: [] };
  return fn;
}
